from taf.internal.robot_typecasts import time_to_seconds, to_boolean
from taf.gnb.oam.coam.admin.legacy.ute_admin.util import ProvidedContent


class CustomerProcedures(object):
    """
    Interface class for customer procedures
    """

    def check_amplifier(self, timeout=60):
        """Check amplifier.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: amplifier info
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "checkAmplifier", {}, timeout).get(ProvidedContent.request_message)

    def check_anntenas(self, timeout=60):
        """Check anntenas.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: anntenas info
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "checkAntennas", {}, timeout).get(ProvidedContent.request_message)

    def check_clock(self, timeout=60):
        """Check clock.

        :param float timeout: Time to wait for positive procedure result.
        


        :rtype: dict
        :return: clock
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "checkClock", {}, timeout).get(ProvidedContent.request_message)

    def check_fans(self, timeout=60):
        """Check fans.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: fans info
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "checkFans", {}, timeout).get(ProvidedContent.request_message)

    def check_hw(self, timeout=60):
        """Check hw.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: HW info
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "checkHw", {}, timeout).get(ProvidedContent.request_message)

    def check_power(self, timeout=60):
        """Check power.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: Power
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "checkPower", {}, timeout).get(ProvidedContent.request_message)

    def check_vswr(self, timeout=60):
        """Check vswr.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: Vswr
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "checkVswr", {}, timeout).get(ProvidedContent.request_message)

    def get_rf_output_power(self, lncel_dist_name, timeout=60):
        """Check RF output power.

        :param string lncel_dist_name: LNCELL distName.
        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: SupportPower
        """

        timeout = time_to_seconds(timeout)
        parameters = {"id": lncel_dist_name}
        return self._api_client.execute_customer_procedure(
            "getSupportPower", parameters, timeout).get(ProvidedContent.request_message)

    def check_link_status(self, timeout=60):
        """Check link status.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: ActiveSessionList
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "getActiveSessionList", {}, timeout).get(ProvidedContent.request_message)

    def get_gps_status(self, timeout=60):
        """get gps status.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: GPS status
        """

        timeout = time_to_seconds(timeout)

        return self._api_client.execute_customer_procedure(
            "getGpsInventoryList", {}, timeout).get(ProvidedContent.request_message)

    def radio_reset_at_layer_1(self, dist_name, reset_type, timeout=60):
        """radio reset layer 1.

        :param string rmod_dist_name: RMOD distName.
                                      From SBTS17A onwards it is recommended to use runtime view dist name
        :param string reset_type: Soft, Hard, Warm
        :param float timeout: Time to wait for positive procedure result.
        
        """

        timeout = time_to_seconds(timeout)
        parameters = {"distName": dist_name, "resetType": reset_type}
        self._api_client.execute_procedure(
            "unitReset", parameters, timeout)

    def reset_cell(self, cell_id, timeout=60):
        """Cell reset available from 18A.

        :param string cell_id: LNCEL|WNCEL|GNCEL distName
        :param float timeout: Time to wait for positive procedure result.
        
        """

        timeout = time_to_seconds(timeout)
        parameters = {"id": cell_id}
        self._api_client.execute_customer_procedure(
            "resetCell", parameters, timeout)

    def reset_all_cells(self, technology, timeout=60):
        """All cells reset available from 18A.

        :param string technology: LTE|WCDMA|GSM
        :param float timeout: Time to wait for positive procedure result.
        
        """

        timeout = time_to_seconds(timeout)
        parameters = {"technology": technology}
        self._api_client.execute_customer_procedure(
            "resetAllCells", parameters, timeout)

    def reset(self, reset_coverage="Site", wait_for_reconnection=True, timeout=300):
        """Site/BTS reset available from 18A.

        :param string reset_coverage: Site|Bts
        :param bool wait_for_reconnection: enable or disable waiting for reconnection after reset
        :param float timeout: Time to wait for positive procedure result.
        
        """

        wait_for_reconnection = to_boolean(wait_for_reconnection)
        reset_coverage = str(reset_coverage).capitalize()
        assert reset_coverage in ("Site", "Bts")
        timeout = time_to_seconds(timeout)
        parameters = {"waitForReconnection": wait_for_reconnection,
                      "resetCoverage": reset_coverage}
        self._api_client.execute_customer_procedure(
            "reset", parameters, timeout)

    def get_timing_status(self, timeout=60):
        """Get timing status.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: timing status
        """

        timeout = time_to_seconds(timeout)
        parameters = {}
        return self._api_client.execute_customer_procedure(
            "getTimingStatus", parameters, timeout).get(ProvidedContent.request_message)

    def get_synchronization_information(self, timeout=60):
        """Get synchronization information.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: synchronization information
        """

        timeout = time_to_seconds(timeout)
        parameters = {}
        return self._api_client.execute_customer_procedure(
            "getSynchronizationInformation", parameters, timeout).get(ProvidedContent.request_message)

    def get_gps_inventory_by_id(self, dist_name, timeout=60):
        """Get gps inventory information.

        :param string dist_name: GPS inventory ID
        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: GPs inventory information
        """

        timeout = time_to_seconds(timeout)
        str(dist_name)
        return self._api_client.execute_customer_procedure(
            "getGpsInventoryById", {"id": dist_name}, timeout).get(ProvidedContent.request_message)

    def get_frequency_history_file_cp(self, dist_name, destination_file="frequency_history_file.json", timeout=60):
        """Get a file with frequency history.

        :param string dist_name: SMOD distName
        :param string destination_file: destination file name
        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: dict with <base64 encoded file content or --output-file argument>
        """

        timeout = time_to_seconds(timeout)
        str(dist_name)
        return self._api_client.execute_customer_procedure(
            "getFrequencyHistoryFile", {"id": dist_name},
            timeout,
            output_file_name=destination_file).get(ProvidedContent.request_message)

    def unit_reset_cp(self, dist_name, reset_type, timeout=60):
        """Get a file with frequency history.

        :param string dist_name: RMOD|GNSSE|GNSSI|RETU|ALD|BBMOD|ASIRMOD distName
        :param string reset_type: Soft|Hard|Warm
        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: dict with procedure status
        """

        timeout = time_to_seconds(timeout)
        str(dist_name)
        reset_type = str(reset_type).capitalize()
        assert reset_type in ("Soft", "Hard", "Warm")
        return self._api_client.execute_customer_procedure(
            "unitReset", {"id": dist_name, "resetType": reset_type}, timeout).get(ProvidedContent.request_message)

    def rollback_software_cp(self, timeout=300):
        """Perform software rollback - customer procedure.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: string
        :return: software rollback status
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_customer_procedure(
            "swRollback", {}, timeout).get(ProvidedContent.request_message)
